using System;
using System.Collections.Generic;
using Microsoft.EntityFrameworkCore;

namespace Models.HelixStudio;

public partial class HelixStudioDbContext : DbContext
{
    public HelixStudioDbContext(DbContextOptions<HelixStudioDbContext> options)
        : base(options)
    {
    }

    public virtual DbSet<monitor> monitors { get; set; }

    public virtual DbSet<vw_monitor> vw_monitors { get; set; }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<monitor>(entity =>
        {
            entity.HasKey(e => e.id).HasName("monitor_pkey");

            entity.ToTable("monitor", "dbo", tb => tb.HasComment("程式監控：一件事一列（crash、hang、end、priority、suspend、resume、ease、unease、limit、first、autorun、listen），seen 見過的程式、startup 見過的開機自動執行、columns 排成欄的量測項目；一支程式現在的限制是它最新的那一列 limit"));

            entity.HasIndex(e => e.type, "monitor_columns")
                .IsUnique()
                .HasFilter("((type)::text = 'columns'::text)");

            entity.HasIndex(e => e.record_id, "monitor_record")
                .IsUnique()
                .HasFilter("(record_id IS NOT NULL)");

            entity.Property(e => e.id).HasComment("流水號");
            entity.Property(e => e.address).HasComment("[listen] 聽的位址與埠；[IPv6]:埠 最長 53");
            entity.Property(e => e.block).HasComment("[limit] 不准連網路");
            entity.Property(e => e.code).HasComment("[crash] 例外碼，例如 0xc0000005");
            entity.Property(e => e.columns).HasComment("[columns] 排成欄的量測項目代碼，照排列的先後");
            entity.Property(e => e.cpu_pct).HasComment("[limit] CPU 上限 %；空的是不限");
            entity.Property(e => e.created_at)
                .HasDefaultValueSql("now()")
                .HasComment("這一列建立的時刻");
            entity.Property(e => e.exe_path).HasComment("程式的完整路徑，照 Windows 給的大小寫，比對時不分大小寫；.NET 閃退的記錄只有檔名時就是檔名");
            entity.Property(e => e.happened_at).HasComment("[事件] 發生的時刻；從 Windows 事件記錄補進來的照它記的時刻");
            entity.Property(e => e.location).HasComment("[startup][autorun] 在那裡的哪一項：登錄檔的機碼與值名稱、啟動資料夾的檔名、排程工作的路徑、服務名稱");
            entity.Property(e => e.mem_mb).HasComment("[limit] 記憶體上限 MB；空的是不限");
            entity.Property(e => e.module).HasComment("[crash] 出錯的模組檔名");
            entity.Property(e => e.name).HasComment("[事件] 程式名稱：它自己的檔案描述，沒有就是檔名；外部給的，沒有上限");
            entity.Property(e => e.other_path).HasComment("[ease][unease] 被暫停、被繼續的那一支程式的路徑");
            entity.Property(e => e.priority_from).HasComment("[priority][ease][unease] 改之前的 Windows 優先順序類別值");
            entity.Property(e => e.priority_to).HasComment("[priority][ease][unease] 改之後的 Windows 優先順序類別值");
            entity.Property(e => e.protocol).HasComment("[listen] TCP 或 UDP");
            entity.Property(e => e.record_id).HasComment("[crash][hang] Windows 事件記錄的編號；從那裡補進來的才有");
            entity.Property(e => e.seconds).HasComment("[hang] 沒有回應幾秒");
            entity.Property(e => e.source).HasComment("[startup][autorun] 從哪裡自動執行：run 登錄檔 Run、runonce 登錄檔 RunOnce、folder 啟動資料夾、task 排程工作、service 服務");
            entity.Property(e => e.type).HasComment("crash＝閃退；hang＝沒有回應；end＝在這台按住結束；priority＝改優先順序；suspend＝暫停；resume＝繼續；ease＝緩和；unease＝取消緩和；limit＝設一次限制；first＝第一次出現；autorun＝新增開機自動執行；listen＝開始聽一個埠；seen＝見過的程式；startup＝見過的開機自動執行；columns＝排成欄的量測項目");
            entity.Property(e => e.up_kbps).HasComment("[limit] 上傳上限 KB/s；空的是不限");
            entity.Property(e => e.updated_at)
                .HasDefaultValueSql("now()")
                .HasComment("這一列最後修改的時刻");
        });

        modelBuilder.Entity<vw_monitor>(entity =>
        {
            entity.ToView("vw_monitor", "dbo");

            entity.Property(e => e.address).HasComment("[event] 開始聽的位址與埠");
            entity.Property(e => e.at_text).HasComment("[event] 發生的時刻 MM-DD HH24:MI:SS；[since] 最早一筆 MM-DD HH24:MI");
            entity.Property(e => e.block).HasComment("[event][limit] 不准連網路");
            entity.Property(e => e.code).HasComment("[event] 閃退的例外碼");
            entity.Property(e => e.columns).HasComment("[columns] 排成欄的量測項目代碼");
            entity.Property(e => e.cpu_pct).HasComment("[event][limit] CPU 上限 %；空的是不限");
            entity.Property(e => e.crash_count).HasComment("[crashes] 閃退幾次");
            entity.Property(e => e.event_type).HasComment("[event] 哪一種事（見 monitor.type）；畫面上的事件名照它寫在 XAML");
            entity.Property(e => e.exe_path).HasComment("[event][limit][crashes][seen][startup] 程式的路徑");
            entity.Property(e => e.id).HasComment("[event][limit][seen][startup][columns] monitor 那一列的流水號（寫回去照它換整列）");
            entity.Property(e => e.location).HasComment("[event][startup] 在那裡的哪一項");
            entity.Property(e => e.mem_mb).HasComment("[event][limit] 記憶體上限 MB；空的是不限");
            entity.Property(e => e.module).HasComment("[event] 閃退時出錯的模組");
            entity.Property(e => e.name).HasComment("[event][limit] 程式名稱");
            entity.Property(e => e.other_path).HasComment("[event] 緩和時被暫停、被繼續的那一支");
            entity.Property(e => e.priority_from).HasComment("[event] 改之前的優先順序類別值");
            entity.Property(e => e.priority_to).HasComment("[event] 改之後的優先順序類別值");
            entity.Property(e => e.protocol).HasComment("[event] 開始聽的埠的協定");
            entity.Property(e => e.record_id).HasComment("[event] Windows 事件記錄的編號（從那裡補進來的閃退、無回應）");
            entity.Property(e => e.seconds).HasComment("[event] 沒有回應幾秒");
            entity.Property(e => e.sort).HasComment("[event] 新的在前");
            entity.Property(e => e.source).HasComment("[event][startup] 從哪裡自動執行（見 monitor.source）");
            entity.Property(e => e.type).HasComment("event＝一件事；limit＝一支程式現在的限制；crashes＝一支程式閃退幾次；seen＝見過的程式；startup＝見過的開機自動執行；columns＝排成欄的量測項目；since＝從什麼時候開始記錄");
            entity.Property(e => e.up_kbps).HasComment("[event][limit] 上傳上限 KB/s；空的是不限");
        });

        OnModelCreatingPartial(modelBuilder);
    }

    partial void OnModelCreatingPartial(ModelBuilder modelBuilder);
}
